package kr.yuumi97.core.rpg;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.inventory.ItemStack;import org.bukkit.scheduler.BukkitTask;import org.bukkit.util.Transformation;import org.joml.Quaternionf;import org.joml.Vector3f;import java.util.*;import java.util.function.*;

/** One animation clock for every transient mesh, including graceful particle-only casts. */
public final class SkillVfxChoreographer {
 public static final List<String> MODELS=List.of("vfx_slash_crescent_gold","vfx_slash_crimson_heavy","vfx_titan_greatsword_drop","vfx_slash_crescent_shadow","vfx_shadow_mark_crest","vfx_star_arrow_volley","vfx_astral_bow_sigil","vfx_magic_circle_arcane","vfx_gravity_singularity","vfx_arcane_meteor","vfx_magic_circle_sanctuary","vfx_holy_spear","vfx_golden_fishing_vortex","vfx_feast_cauldron_aura");
 private record MarkKey(UUID caster,UUID target){}
 private static final class Animation {Player owner;RpgDomain domain;String identity,model;Location from,to,previous;LivingEntity follow;Supplier<Location> path;BooleanSupplier visible;ItemDisplay display;int age,duration;long markUntil;float first,last,spin;boolean moving;Vector3f direction;Animation(Player p,RpgDomain d,String identity,String model,Location from,Location to,int duration,float first,float last,float spin){owner=p;domain=d;this.identity=identity;this.model=model;this.from=from.clone();this.to=to.clone();previous=from.clone();this.duration=Math.max(1,duration);this.first=first;this.last=last;this.spin=spin;moving=from.distanceSquared(to)>1.e-8;org.bukkit.util.Vector initial=moving?to.toVector().subtract(from.toVector()):p.getLocation().getDirection().setY(0);direction=new Vector3f((float)initial.getX(),(float)initial.getY(),(float)initial.getZ());}}
 private final RpgJobManager r;private final List<Animation> active=new ArrayList<>();private final Map<MarkKey,Animation> crests=new HashMap<>();private BukkitTask task;SkillVfxChoreographer(RpgJobManager r){this.r=r;}
 public void start(){task=Bukkit.getScheduler().runTaskTimer(r.plugin,this::tick,1,1);}public void stop(){if(task!=null)task.cancel();active.forEach(a->{if(a.display!=null)a.display.remove();});active.clear();crests.clear();}
 private String identity(Player p,RpgDomain d){return String.valueOf(d==RpgDomain.COMBAT?r.getCombat(p):r.getLife(p));}
 public ItemDisplay play(Player p,RpgDomain d,String model,Location from,Location to,int ticks,float first,float last,float spin){Animation a=new Animation(p,d,identity(p,d),model,from,to,ticks,first,last,spin);
  if(r.hasModel(model)&&active.size()<r.cfg("rpg.vfx.max-displays",320)){a.display=from.getWorld().spawn(unrotated(from),ItemDisplay.class,e->{e.setItemStack(r.prop(model,Material.PAPER));e.setItemDisplayTransform(ItemDisplay.ItemDisplayTransform.NONE);e.setInterpolationDelay(0);e.setInterpolationDuration(2);e.setTeleportDuration(2);e.setPersistent(false);e.setBrightness(new Display.Brightness(15,15));e.setTransformation(transform(a,first));});}
  active.add(a);return a.display;}
 public void circle(Player p,RpgDomain d,String model,Location at,double radius,int ticks){float scale=(float)(radius*2/2.75);play(p,d,model,at.clone().add(0,.05,0),at.clone().add(0,.05,0),ticks,scale*.15f,scale,.04f);}
 public void slash(Player p,String model,double range){Location at=p.getLocation().add(0,1,0);play(p,RpgDomain.COMBAT,model,at,at,7,(float)range*.55f,(float)range*.72f,.22f);}
 public void drop(Player p,String model,Location at,double height,int ticks){double drift=model.equals("vfx_arcane_meteor")?height*.35:0;play(p,RpgDomain.COMBAT,model,at.clone().add(-drift,height,-drift),at,ticks,1.5f,1.5f,0);}
 public void projectile(Player p,String model,Location from,Location to,int ticks,float scale){play(p,RpgDomain.COMBAT,model,from,to,ticks,scale,scale,0);}
 public void track(Player p,String model,Location start,Supplier<Location> path,BooleanSupplier visible,int ticks,float scale){play(p,RpgDomain.COMBAT,model,start,start,ticks,scale,scale,0);Animation a=active.getLast();a.path=path;a.visible=visible;a.moving=true;org.bukkit.util.Vector aim=p.getEyeLocation().getDirection();a.direction.set((float)aim.getX(),(float)aim.getY(),(float)aim.getZ());if(a.display!=null)a.display.setTransformation(transform(a,scale));}
 public void mark(Player p,LivingEntity target,int stacks){MarkKey key=new MarkKey(p.getUniqueId(),target.getUniqueId());Animation a=crests.get(key);float scale=.3f+stacks*.1f;if(a==null){Location at=target.getLocation().add(0,target.getHeight()+.6,0);play(p,RpgDomain.COMBAT,"vfx_shadow_mark_crest",at,at,160,scale,scale,.08f);a=active.getLast();a.follow=target;crests.put(key,a);}a.age=0;a.first=scale;a.last=scale;a.markUntil=System.currentTimeMillis()+8000;}
 public void clearMark(Player p,LivingEntity target){Animation a=crests.remove(new MarkKey(p.getUniqueId(),target.getUniqueId()));if(a!=null){if(a.display!=null)a.display.remove();active.remove(a);}}
 public void clearTarget(LivingEntity target){Set<Animation> remove=new HashSet<>();crests.entrySet().removeIf(e->{if(e.getKey().target.equals(target.getUniqueId())){remove.add(e.getValue());return true;}return false;});for(Animation a:remove){if(a.display!=null)a.display.remove();active.remove(a);}}
 public void clear(Player p,RpgDomain d){active.removeIf(a->{if(a.owner.equals(p)&&a.domain==d){if(a.display!=null)a.display.remove();crests.values().removeIf(v->v==a);return true;}return false;});}
 private void tick(){Iterator<Animation> it=active.iterator();while(it.hasNext()){Animation a=it.next();if(++a.age>a.duration||a.markUntil>0&&a.markUntil<=System.currentTimeMillis()||!RpgJobManager.usable(a.owner)||!identity(a.owner,a.domain).equals(a.identity)||!a.owner.getWorld().equals(a.from.getWorld())||a.follow!=null&&(!a.follow.isValid()||a.follow.isDead()||!a.follow.getWorld().equals(a.owner.getWorld()))||a.visible!=null&&!a.visible.getAsBoolean()){if(a.display!=null)a.display.remove();crests.values().removeIf(v->v==a);it.remove();continue;}
   double t=a.age/(double)a.duration;Location at=a.path!=null?a.path.get():a.follow!=null?a.follow.getLocation().add(0,a.follow.getHeight()+.6,0):a.from.clone().add(a.to.toVector().subtract(a.from.toVector()).multiply(t));float scale=a.first+(a.last-a.first)*(float)Math.min(1,t*4);
   if(a.moving){org.bukkit.util.Vector delta=at.toVector().subtract(a.previous.toVector());if(delta.lengthSquared()>1.e-8)a.direction.set((float)delta.getX(),(float)delta.getY(),(float)delta.getZ());}a.previous=at.clone();
   if(a.display!=null&&a.display.isValid()){a.display.teleport(unrotated(at));a.display.setTransformation(transform(a,scale));}
   else if(a.age%3==0){Color color=a.model.contains("shadow")||a.model.contains("arcane")||a.model.contains("gravity")?Color.fromRGB(180,105,235):a.model.contains("arrow")||a.model.contains("fishing")?Color.fromRGB(54,207,201):Color.fromRGB(255,214,102);double radius=Math.max(.2,scale*.7);for(int i=0;i<12;i++){double angle=i*Math.PI/6+a.age*.08;at.getWorld().spawnParticle(Particle.DUST,at.clone().add(Math.cos(angle)*radius,0,Math.sin(angle)*radius),1,0,0,0,0,new Particle.DustOptions(color,1.2f));}}
  }}
 private static Location unrotated(Location at){Location copy=at.clone();copy.setYaw(0);copy.setPitch(0);return copy;}
 private static Transformation transform(Animation a,float scale){Vector3f axis=a.moving&&(a.model.equals("vfx_holy_spear")||a.model.equals("vfx_titan_greatsword_drop")||a.model.equals("vfx_arcane_meteor"))?new Vector3f(0,-1,0):new Vector3f(0,0,-1);Quaternionf rotation=orientation(axis,a.direction,a.moving?a.spin*a.age:0);if(!a.moving)rotation.rotateY(a.spin*a.age);return new Transformation(new Vector3f(),rotation,new Vector3f(scale),new Quaternionf());}
 static Quaternionf orientation(Vector3f axis,Vector3f direction,float spin){Vector3f forward=new Vector3f(direction);if(!forward.isFinite()||forward.lengthSquared()<1.e-8f)forward.set(0,0,-1);forward.normalize();return new Quaternionf().rotationTo(axis,forward).rotateAxis(spin,axis.x,axis.y,axis.z);}
}
